			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.DCVI.Pins("VDD1").ComplianceRange(tlDCVIComplianceBoth) = 10;
			Globals.TheHdw.DCVI.Pins("VDD1").ComplianceRange[Globals.tlDCVIComplianceBoth] = 10;
			
			//VDD1 1p8/1p8
			
			//OriginalCode: .SetVoltageAndRange 1.8, 10;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.DCVI.Pins("VDD1").SetVoltageAndRange(1.8, 10);
			Globals.TheHdw.DCVI.Pins("VDD1").SetVoltageAndRange(1.8, 10);
			
