						//PseudoCode  : VariableAssignment: Name: FailCount(i)(nSite); AssignedValue: TheHdw.Pins(OutPinsArray(i)).FailCount(nSite);
						FailCount[i].Value[nSite] = Globals.TheHdw.Pins.Pins(OutPinsArray[i]).FailCount.Value[nSite];
						
						//OriginalCode: If FailCount(i)(nSite) = 0 Then;
						//PseudoCode  : If: Condition: FailCount(i)(nSite) = 0;
						if (FailCount[i].Value[nSite] == 0)
						{
							//VihVoltage(i)(nSite) = VihVoltage(i)(nSite) - 100 * mV
							
							//OriginalCode: VihVoltage(i)(nSite) = VihVoltage(i)(nSite) - 10 * mV;
							//PseudoCode  : VariableAssignment: Name: VihVoltage(i)(nSite); AssignedValue: VihVoltage(i)(nSite) - 10 * mV;
							VihVoltage[i].Value[nSite] = VihVoltage[i].Value[nSite] - 10 * Globals.mV;
							
							//OriginalCode: Else;
							//PseudoCode  : Else;
						}
						else
						{
							//VihVoltage(i)(nSite) = VihVoltage(i)(nSite) + 100 * mV
							
							//OriginalCode: VihVoltage(i)(nSite) = VihVoltage(i)(nSite) + 10 * mV;
							//PseudoCode  : VariableAssignment: Name: VihVoltage(i)(nSite); AssignedValue: VihVoltage(i)(nSite) + 10 * mV;
							VihVoltage[i].Value[nSite] = VihVoltage[i].Value[nSite] + 10 * Globals.mV;
							
							//OriginalCode: End If;
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: Wend;
						//PseudoCode  : EndWhileLoop;
					}
					
					//OriginalCode: Call TheHdw.PinLevels.Pins(InPinsArray(i)).ModifyLevel(chVih, VihInitVoltage(i)(nSite));
					//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.PinLevels.Pins(InPinsArray(i)).ModifyLevel(chVih, VihInitVoltage(i)(nSite));
					Globals.TheHdw.PinLevels.Pins(InPinsArray[i]).ModifyLevel(Globals.chVih,VihInitVoltage[i].Value[nSite]);
					
					//OriginalCode: Next i;
					//PseudoCode  : EndForLoop: VariableName: i;
				}
				
				//OriginalCode: Next nSite;
				//PseudoCode  : EndForLoop: VariableName: nSite;
				GlobalFunctions.EndSiteLoop(nSite);
			}
			
			//Set or clear postbody relays
			
			//Re-Apply original levels and timing
			
			//OriginalCode: TheHdw.Digital.ApplyLevelsTiming True, True, True, tlPowered;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.ApplyLevelsTiming(True, True, True, tlPowered);
