			while ((FailCount[0](SiteNum) == 0 && VihCoarseVoltage[0] > VilInitVoltage[0](SiteNum)))
			{
				//OriginalCode: Call TheHdw.PinLevels.Pins(InPinsArray(0)).ModifyLevel(chVih, VihCoarseVoltage(0));
