			//OriginalCode: TheHdw.Digital.ApplyLevelsTiming True, True, True, tlPowered;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.ApplyLevelsTiming(True, True, True, tlPowered);
			Globals.TheHdw.Digital.ApplyLevelsTiming(ConnectAllPins: true, loadLevels: true, loadTiming: true, RelayMode: Globals.tlPowered, InitPinsHi: null, InitPinsLo: null, InitPinsHiz: null);
			
			//OriginalCode: For i = 0 To UBound(InPinsArray);
			//PseudoCode  : ForLoop: VariableName: i; Start: 0; Stop: UBound(InPinsArray); StepSize: 1;
			for (i = 0; i <= GlobalFunctions.UBound(InPinsArray); i = i + 1)
			{
				//OriginalCode: TheExec.Flow.TestLimit VilVoltage(i), ScaleType:=scaleNoScaling, unit:=unitVolt, ForceResults:=tlForceFlow;
				//PseudoCode  : AsIsLineOfCode: LineOfCode: TheExec.Flow.TestLimit(VilVoltage(i), ScaleType:=scaleNoScaling, unit:=unitVolt, ForceResults:=tlForceFlow);
