				Done.Value[nSite] = false;
				
				//OriginalCode: FailCounter = 0;
				//PseudoCode  : VariableAssignment: Name: FailCounter; AssignedValue: 0;
				FailCounter = 0;
				
				//OriginalCode: While (FailCounter < OutPinsNum);
				//PseudoCode  : WhileLoop: Condition: (FailCounter < OutPinsNum);
				while ((FailCounter < OutPinsNum))
				{
					//Clear Pattern Fail Count
					
					//OriginalCode: For i = 0 To UBound(OutPinsArray);
					//PseudoCode  : ForLoop: VariableName: i; Start: 0; Stop: UBound(OutPinsArray); StepSize: 1;
					for (i = 0; i <= GlobalFunctions.UBound(OutPinsArray); i = i + 1)
					{
						//OriginalCode: TheHdw.Digital.Patgen.ClearFailCount;
						//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Patgen.ClearFailCount();
						Globals.TheHdw.Digital.Patgen.ClearFailCount();
						
						//Run the Pattern
						
						//Call thehdw.Digital.Patterns.Pat(".\\vectors\\func_tPWL_10M").Load
						
						//OriginalCode: Call TheHdw.Digital.Patterns.Pat(".\\vectors\\func_tPWL_10M").Run;
						//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Patterns.Pat(".\\vectors\\func_tPWL_10M").Run();
						Globals.TheHdw.Digital.Patterns.Pat(".\\vectors\\func_tPWL_10M").Run();
						
						//Check Pattern Status
						
						//OriginalCode: FailFlag(i)(nSite) = TheHdw.Digital.PinSiteFailed(OutPinsArray(i), SiteNum);
						//PseudoCode  : VariableAssignment: Name: FailFlag(i)(nSite); AssignedValue: TheHdw.Digital.PinSiteFailed(OutPinsArray(i), SiteNum);
						FailFlag[i].Value[nSite] = Globals.TheHdw.Digital.PinSiteFailed(OutPinsArray[i],SiteNum);
						
						//OriginalCode: If (FailFlag(i)(nSite) = True) And (First = True) Then;
						//PseudoCode  : If: Condition: (FailFlag(i)(nSite) = True) And (First = True);
						if ((FailFlag[i].Value[nSite] == true) && (First == true))
						{
							//OriginalCode: First = False;
							//PseudoCode  : VariableAssignment: Name: First; AssignedValue: False;
							First = false;
							
							//OriginalCode: With TheHdw.Digital.Timing;
							//OriginalCode: .EdgeTime(chEdgeR0) = R0_OutputEdge + 5 * ns;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.EdgeTime(chEdgeR0) = R0_OutputEdge + 5 * ns;
							Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeR0] = R0_OutputEdge + 5 * Globals.nS;
							
							//OriginalCode: .Pins(OutPins).WriteEdgeTimingRAM (TsetName);
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.Pins(OutPins).WriteEdgeTimingRAM(TsetName);
							Globals.TheHdw.Digital.Timing.Pins(OutPins).WriteEdgeTimingRAM(TsetName);
							
							//OriginalCode: End With;
							//OriginalCode: TheHdw.Digital.Patgen.ClearFailCount;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Patgen.ClearFailCount();
							Globals.TheHdw.Digital.Patgen.ClearFailCount();
							
							//Run the Pattern
							
							//Call thehdw.Digital.Patterns.Pat(".\\vectors\\func_tPWL_10M").Load
							
							//OriginalCode: Call TheHdw.Digital.Patterns.Pat(".\\vectors\\func_tPWL_10M").Run;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Patterns.Pat(".\\vectors\\func_tPWL_10M").Run();
							Globals.TheHdw.Digital.Patterns.Pat(".\\vectors\\func_tPWL_10M").Run();
							
							//Check Pattern Status
							
							//OriginalCode: FailFlag(i)(nSite) = TheHdw.Digital.PinSiteFailed(OutPinsArray(i), SiteNum);
							//PseudoCode  : VariableAssignment: Name: FailFlag(i)(nSite); AssignedValue: TheHdw.Digital.PinSiteFailed(OutPinsArray(i), SiteNum);
							FailFlag[i].Value[nSite] = Globals.TheHdw.Digital.PinSiteFailed(OutPinsArray[i],SiteNum);
							
							//OriginalCode: End If;
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: First = False;
						//PseudoCode  : VariableAssignment: Name: First; AssignedValue: False;
						First = false;
						
						//OriginalCode: If (FoundEdge(i) > 0) Then GoTo Continue:;
						//PseudoCode  : If: Condition: (FoundEdge(i) > 0);
						if ((FoundEdge[i].Value[nSite] > 0))
						{
							//PseudoCode  : GoToCommand: Label: Continue;
							goto Continue;
							
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: If (FailFlag(i)(nSite)) Then;
						//PseudoCode  : If: Condition: (FailFlag(i)(nSite));
						if ((FailFlag[i].Value[nSite]))
						{
							//OriginalCode: FailCounter = FailCounter + 1;
							//PseudoCode  : VariableAssignment: Name: FailCounter; AssignedValue: FailCounter + 1;
							FailCounter = FailCounter + 1;
							
							//OriginalCode: FoundEdge(i) = InputTrailingEdge + StepSize;
							//PseudoCode  : VariableAssignment: Name: FoundEdge(i); AssignedValue: InputTrailingEdge + StepSize;
							FoundEdge[i].Value[nSite] = InputTrailingEdge + StepSize;
							
							//OriginalCode: End If;
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: If FailCounter = (UBound(OutPinsArray) + 1) Then;
						//PseudoCode  : If: Condition: FailCounter = (UBound(OutPinsArray) + 1);
						if (FailCounter == (GlobalFunctions.UBound(OutPinsArray) + 1))
						{
							//OriginalCode: Done(nSite) = True;
							//PseudoCode  : VariableAssignment: Name: Done(nSite); AssignedValue: True;
							Done.Value[nSite] = true;
							
							//OriginalCode: NumSitesDone = NumSitesDone + 1;
							//PseudoCode  : VariableAssignment: Name: NumSitesDone; AssignedValue: NumSitesDone + 1;
							NumSitesDone = NumSitesDone + 1;
							
							//OriginalCode: InputTrailingEdge = InputTrailingEdge + StepSize;
							//PseudoCode  : VariableAssignment: Name: InputTrailingEdge; AssignedValue: InputTrailingEdge + StepSize;
							InputTrailingEdge = InputTrailingEdge + StepSize;
							
							//OriginalCode: End If;
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: Continue:;
						//PseudoCode  : GoToLabel: Name: Continue;
Continue:
						
						//OriginalCode: If (i = InPinsNum - 1) Then;
						//PseudoCode  : If: Condition: (i = InPinsNum - 1);
						if ((i == InPinsNum - 1))
						{
							//OriginalCode: InputTrailingEdge = InputTrailingEdge - StepSize;
							//PseudoCode  : VariableAssignment: Name: InputTrailingEdge; AssignedValue: InputTrailingEdge - StepSize;
							InputTrailingEdge = InputTrailingEdge - StepSize;
							
							//OriginalCode: End If;
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: If (InputTrailingEdge >= D1_InputEdge) And (Not Done(nSite)) And (i = InPinsNum - 1) Then;
						//PseudoCode  : If: Condition: (InputTrailingEdge >= D1_InputEdge) And (Not Done(nSite)) And (i = InPinsNum - 1);
						if ((InputTrailingEdge >= D1_InputEdge) && (NotDone.Value[nSite]) && (i == InPinsNum - 1))
						{
							//Set New TrailingEdge (D2_Edge) Location
							
							//OriginalCode: With TheHdw.Digital.Timing;
							//OriginalCode: .EdgeTime(chEdgeD2) = InputTrailingEdge;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.EdgeTime(chEdgeD2) = InputTrailingEdge;
							Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeD2] = InputTrailingEdge;
							
							//OriginalCode: .EdgeTime(chEdgeD1) = D1_InputEdge;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.EdgeTime(chEdgeD1) = D1_InputEdge;
							Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeD1] = D1_InputEdge;
							
							//OriginalCode: .EdgeTime(chEdgeD0) = D0_InputEdge;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.EdgeTime(chEdgeD0) = D0_InputEdge;
							Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeD0] = D0_InputEdge;
							
							//OriginalCode: .EdgeTime(chEdgeD3) = D3_InputEdge;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.EdgeTime(chEdgeD3) = D3_InputEdge;
							Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeD3] = D3_InputEdge;
							
							//OriginalCode: .EdgeTime(chEdgeR0) = R0_InputEdge;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.EdgeTime(chEdgeR0) = R0_InputEdge;
							Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeR0] = R0_InputEdge;
							
							//.Pins(InPinsArray(i)).WriteEdgeTimingRAM (TsetName)
							
							//added from original above 2-5-13
							
							//OriginalCode: .Pins(InPins).WriteEdgeTimingRAM (TsetName);
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.Pins(InPins).WriteEdgeTimingRAM(TsetName);
							Globals.TheHdw.Digital.Timing.Pins(InPins).WriteEdgeTimingRAM(TsetName);
							
							//OriginalCode: End With;
							//OriginalCode: End If;
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: Next i;
						//PseudoCode  : EndForLoop: VariableName: i;
					}
					
					//OriginalCode: Wend;
					//PseudoCode  : EndWhileLoop;
				}
				
				//OriginalCode: TheHdw.Digital.ApplyLevelsTiming True, True, True, tlPowered, , "data_ins";
				//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.ApplyLevelsTiming(True, True, True, tlPowered, , "data_ins");
				Globals.TheHdw.Digital.ApplyLevelsTiming(ConnectAllPins: true, loadLevels: true, loadTiming: true, RelayMode: Globals.tlPowered, InitPinsHi: null, InitPinsLo: "data_ins", InitPinsHiz: null);
				
				//OriginalCode: Next nSite;
				//PseudoCode  : EndForLoop: VariableName: nSite;
				GlobalFunctions.EndSiteLoop(nSite);
			}
			
			//Datalog Results
			
			//OriginalCode: For i = 0 To UBound(InPinsArray);
			//PseudoCode  : ForLoop: VariableName: i; Start: 0; Stop: UBound(InPinsArray); StepSize: 1;
			for (i = 0; i <= GlobalFunctions.UBound(InPinsArray); i = i + 1)
			{
				//OriginalCode: For Each nSite In TheExec.Sites.Active;
				//PseudoCode  : ForEachLoop: ObjectName: nSite; CollectionName: TheExec.Sites.Active;
				foreach (dynamic nSite in Globals.TheExec.Sites.Active)
				{
					GlobalFunctions.BeginSiteLoop(nSite);
					
					//OriginalCode: If D1_InputEdge >= FoundEdge(i)(nSite) Then;
					//PseudoCode  : If: Condition: D1_InputEdge >= FoundEdge(i)(nSite);
					if (D1_InputEdge >= FoundEdge[i].Value[nSite])
					{
						//OriginalCode: Pulse_width(i)(nSite) = 99;
						//PseudoCode  : VariableAssignment: Name: Pulse_width(i)(nSite); AssignedValue: 99;
						Pulse_width[i].Value[nSite] = 99;
						
						//OriginalCode: Else;
						//PseudoCode  : Else;
					}
					else
					{
						//OriginalCode: Pulse_width(i)(nSite) = FoundEdge(i)(nSite) - D1_InputEdge;
						//PseudoCode  : VariableAssignment: Name: Pulse_width(i)(nSite); AssignedValue: FoundEdge(i)(nSite) - D1_InputEdge;
						Pulse_width[i].Value[nSite] = FoundEdge[i].Value[nSite] - D1_InputEdge;
						
						//OriginalCode: End If;
					//PseudoCode  : EndIf;
					}
					
					//OriginalCode: Next nSite;
					//PseudoCode  : EndForLoop: VariableName: nSite;
					GlobalFunctions.EndSiteLoop(nSite);
				}
				
				//OriginalCode: TheExec.Flow.TestLimit resultval:=Pulse_width(i), ScaleType:=scaleNano, unit:=unitTime, ForceResults:=tlForceFlow;
				//PseudoCode  : AsIsLineOfCode: LineOfCode: TheExec.Flow.TestLimit(resultval:=Pulse_width(i), ScaleType:=scaleNano, unit:=unitTime, ForceResults:=tlForceFlow);
				Globals.TheExec.Flow.TestLimit(resultval: Pulse_width[i], ScaleType: Globals.scaleNano, unit: Globals.unitTime, ForceResults: Globals.tlForceFlow);
				
				//OriginalCode: Next i;
				//PseudoCode  : EndForLoop: VariableName: i;
			}
			
			//Set or clear postbody relays
			
			//OriginalCode: Exit Function;
			//PseudoCode  : FunctionExit;
			return;
			
			//OriginalCode: errHandler:;
			
			//PseudoCode  : FunctionEnd;
		}
		///********************************************************/
		
		//minimum_pulse_width Function
		
		//Items necessary to complete this function:
		
		//1. Pattern must pass on initial test.
		
		//2. Strobe on outputs must be placed so that it fails because
		
		//the pulse disappears rather than the missing the edge
		
		//from moving earilier in time
		
		//3. Assume all input edges are coincident
		
		///********************************************************/
		
		//OriginalCode: Public Function minimum_pulse_width_high_10M_2p75_2p75_char(ThePat As PatternSet, InPins As pinlist, TsetName As String, OutPins As pinlist);
