						FailCount[i].Value[nSite] = Globals.TheHdw.Pins.Pins(OutPinsArray[i]).FailCount.Value[nSite];
						
						//OriginalCode: If FailCount(i)(nSite) = 0 Then;
						//PseudoCode  : If: Condition: FailCount(i)(nSite) = 0;
						if (FailCount[i].Value[nSite] == 0)
						{
							//VilVoltage(i)(nSite) = VilVoltage(i)(nSite) + 100 * mV
							
							//OriginalCode: VilVoltage(i)(nSite) = VilVoltage(i)(nSite) + 10 * mV;
							//PseudoCode  : VariableAssignment: Name: VilVoltage(i)(nSite); AssignedValue: VilVoltage(i)(nSite) + 10 * mV;
							VilVoltage[i].Value[nSite] = VilVoltage[i].Value[nSite] + 10 * Globals.mV;
							
							//OriginalCode: Else;
							//PseudoCode  : Else;
						}
						else
						{
							//VilVoltage(i)(nSite) = VilVoltage(i)(nSite) - 100 * mV
							
							//OriginalCode: VilVoltage(i)(nSite) = VilVoltage(i)(nSite) - 10 * mV;
							//PseudoCode  : VariableAssignment: Name: VilVoltage(i)(nSite); AssignedValue: VilVoltage(i)(nSite) - 10 * mV;
							VilVoltage[i].Value[nSite] = VilVoltage[i].Value[nSite] - 10 * Globals.mV;
							
							//OriginalCode: End If;
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: Wend;
						//PseudoCode  : EndWhileLoop;
