			//PseudoCode  : ResizeArray: Name: VihVoltage; LowerBound: 0; UpperBound: TestPinsNum - 1;
			VihVoltage = SiteDouble.New(TestPinsNum - 1);
			
			//OriginalCode: ReDim VilInitVoltage(TestPinsNum - 1);
			//PseudoCode  : ResizeArray: Name: VilInitVoltage; LowerBound: 0; UpperBound: TestPinsNum - 1;
			VilInitVoltage = SiteDouble.New(TestPinsNum - 1);
			
			//OriginalCode: ReDim VihInitVoltage(TestPinsNum - 1);
