				//PseudoCode  : VariableAssignment: Name: FailCount(0)(SiteNum); AssignedValue: TheHdw.Pins(OutPinsArray(0)).FailCount(SiteNum);
				FailCount[0](SiteNum) = Globals.TheHdw.Pins.Pins(OutPinsArray[0]).FailCount[SiteNum];
				
				//OriginalCode: If FailCount(0)(SiteNum) = 0 Then;
				//PseudoCode  : If: Condition: FailCount(0)(SiteNum) = 0;
				if (FailCount[0](SiteNum) == 0)
				{
					//OriginalCode: VilCoarseVoltage(0) = VilCoarseVoltage(0) + 250 * mV;
					//PseudoCode  : VariableAssignment: Name: VilCoarseVoltage(0); AssignedValue: VilCoarseVoltage(0) + 250 * mV;
					VilCoarseVoltage[0] = VilCoarseVoltage[0] + 250 * Globals.mV;
					
					//OriginalCode: Else;
					//PseudoCode  : Else;
				}
				else
				{
					//OriginalCode: Call TheHdw.PinLevels.Pins(InPinsArray(0)).ModifyLevel(chVil, 0);
					//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.PinLevels.Pins(InPinsArray(0)).ModifyLevel(chVil, 0);
					Globals.TheHdw.PinLevels.Pins(InPinsArray[0]).ModifyLevel(Globals.chVil,0);
					
					//OriginalCode: VilCoarseVoltage(0) = VilCoarseVoltage(0) - 250 * mV;
					//PseudoCode  : VariableAssignment: Name: VilCoarseVoltage(0); AssignedValue: VilCoarseVoltage(0) - 250 * mV;
					VilCoarseVoltage[0] = VilCoarseVoltage[0] - 250 * Globals.mV;
					
					//OriginalCode: End If;
				//PseudoCode  : EndIf;
				}
				
				//OriginalCode: Wend;
				//PseudoCode  : EndWhileLoop;
			}
			
			//OriginalCode: For i = 0 To UBound(InPinsArray);
			//PseudoCode  : ForLoop: VariableName: i; Start: 0; Stop: UBound(InPinsArray); StepSize: 1;
			for (i = 0; i <= GlobalFunctions.UBound(InPinsArray); i = i + 1)
			{
