			SiteBoolean[] FailFlag;
			
			//OriginalCode: Dim First As New SiteBoolean;
			//PseudoCode  : VariableDeclaration: Name: First; Type: New SiteBoolean;
			SiteBoolean First = new SiteBoolean();
			
			//OriginalCode: Dim FirstEntry As New SiteBoolean;
			//PseudoCode  : VariableDeclaration: Name: FirstEntry; Type: New SiteBoolean;
			SiteBoolean FirstEntry = new SiteBoolean();
			
			//OriginalCode: Dim Done As New SiteBoolean;
			//PseudoCode  : VariableDeclaration: Name: Done; Type: New SiteBoolean;
			SiteBoolean Done = new SiteBoolean();
			
			//OriginalCode: Dim InPinsNum As Long;
			//PseudoCode  : VariableDeclaration: Name: InPinsNum; Type: Long;
			int InPinsNum = 0;
			
			//OriginalCode: Dim OutPinsNum As Long;
			//PseudoCode  : VariableDeclaration: Name: OutPinsNum; Type: Long;
