			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.DCVI.Pins("VDD2").SetVoltageAndRange(3, 10);
			Globals.TheHdw.DCVI.Pins("VDD2").SetVoltageAndRange(3, 10);
			
