			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.ApplyLevelsTiming(True, True, True, tlPowered, , "data_ins");
			Globals.TheHdw.Digital.ApplyLevelsTiming(ConnectAllPins: true, loadLevels: true, loadTiming: true, RelayMode: Globals.tlPowered, InitPinsHi: null, InitPinsLo: "data_ins", InitPinsHiz: null);
			
			//Should this be a variable? changed from orig above 2-5-13
			
			//OriginalCode: StepSize = 0.125 * ns;
			//PseudoCode  : VariableAssignment: Name: StepSize; AssignedValue: 0.125 * ns;
			StepSize = 0.125 * Globals.nS;
			
			//OriginalCode: For Each nSite In TheExec.Sites.Active;
