				//PseudoCode  : ForLoop: VariableName: i; Start: 0; Stop: UBound(InPinsArray); StepSize: 1;
				for (i = 0; i <= GlobalFunctions.UBound(InPinsArray); i = i + 1)
				{
					//OriginalCode: FailCount(i)(nSite) = 0;
					//PseudoCode  : VariableAssignment: Name: FailCount(i)(nSite); AssignedValue: 0;
					FailCount[i].Value[nSite] = 0;
					
					//VihVoltage(i)(nSite) = 1.1 * V' Temporary
					
					//OriginalCode: VihVoltage(i)(nSite) = VihInitVoltage(i)(nSite) * v;
					//PseudoCode  : VariableAssignment: Name: VihVoltage(i)(nSite); AssignedValue: VihInitVoltage(i)(nSite) * v;
					VihVoltage[i].Value[nSite] = VihInitVoltage[i].Value[nSite] * Globals.V;
					
					//OriginalCode: While (FailCount(i)(nSite) = 0 And VihVoltage(i)(nSite) > VilInitVoltage(i)(nSite));
					//PseudoCode  : WhileLoop: Condition: (FailCount(i)(nSite) = 0 And VihVoltage(i)(nSite) > VilInitVoltage(i)(nSite));
					while ((FailCount[i].Value[nSite] == 0 && VihVoltage[i].Value[nSite] > VilInitVoltage[i].Value[nSite]))
					{
						//OriginalCode: Call TheHdw.PinLevels.Pins(InPinsArray(i)).ModifyLevel(chVih, VihVoltage(i)(nSite));
						//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.PinLevels.Pins(InPinsArray(i)).ModifyLevel(chVih, VihVoltage(i)(nSite));
						Globals.TheHdw.PinLevels.Pins(InPinsArray[i]).ModifyLevel(Globals.chVih,VihVoltage[i].Value[nSite]);
						
						//OriginalCode: Call TheHdw.Digital.Patterns.Pat(".\\vectors\\vil_vih_search").Run;
						//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Patterns.Pat(".\\vectors\\vil_vih_search").Run();
						Globals.TheHdw.Digital.Patterns.Pat(".\\vectors\\vil_vih_search").Run();
						
						//OriginalCode: FailCount(i)(nSite) = TheHdw.Pins(OutPinsArray(i)).FailCount(nSite);
						//PseudoCode  : VariableAssignment: Name: FailCount(i)(nSite); AssignedValue: TheHdw.Pins(OutPinsArray(i)).FailCount(nSite);
						FailCount[i].Value[nSite] = Globals.TheHdw.Pins.Pins(OutPinsArray[i]).FailCount.Value[nSite];
						
						//OriginalCode: If FailCount(i)(nSite) = 0 Then;
						//PseudoCode  : If: Condition: FailCount(i)(nSite) = 0;
						if (FailCount[i].Value[nSite] == 0)
						{
							//VihVoltage(i)(nSite) = VihVoltage(i)(nSite) - 100 * mV
							
							//OriginalCode: VihVoltage(i)(nSite) = VihVoltage(i)(nSite) - 10 * mV;
							//PseudoCode  : VariableAssignment: Name: VihVoltage(i)(nSite); AssignedValue: VihVoltage(i)(nSite) - 10 * mV;
							VihVoltage[i].Value[nSite] = VihVoltage[i].Value[nSite] - 10 * Globals.mV;
							
							//OriginalCode: Else;
							//PseudoCode  : Else;
						}
						else
						{
							//VihVoltage(i)(nSite) = VihVoltage(i)(nSite) + 100 * mV
							
							//OriginalCode: VihVoltage(i)(nSite) = VihVoltage(i)(nSite) + 10 * mV;
							//PseudoCode  : VariableAssignment: Name: VihVoltage(i)(nSite); AssignedValue: VihVoltage(i)(nSite) + 10 * mV;
							VihVoltage[i].Value[nSite] = VihVoltage[i].Value[nSite] + 10 * Globals.mV;
							
							//OriginalCode: End If;
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: Wend;
						//PseudoCode  : EndWhileLoop;
					}
					
					//OriginalCode: Call TheHdw.PinLevels.Pins(InPinsArray(i)).ModifyLevel(chVih, VihInitVoltage(i)(nSite));
					//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.PinLevels.Pins(InPinsArray(i)).ModifyLevel(chVih, VihInitVoltage(i)(nSite));
					Globals.TheHdw.PinLevels.Pins(InPinsArray[i]).ModifyLevel(Globals.chVih,VihInitVoltage[i].Value[nSite]);
					
					//OriginalCode: Next i;
					//PseudoCode  : EndForLoop: VariableName: i;
				}
				
				//OriginalCode: Next nSite;
				//PseudoCode  : EndForLoop: VariableName: nSite;
				GlobalFunctions.EndSiteLoop(nSite);
			}
			
			//Set or clear postbody relays
			
			//Re-Apply original levels and timing
			
			//OriginalCode: TheHdw.Digital.ApplyLevelsTiming True, True, True, tlPowered;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.ApplyLevelsTiming(True, True, True, tlPowered);
			Globals.TheHdw.Digital.ApplyLevelsTiming(ConnectAllPins: true, loadLevels: true, loadTiming: true, RelayMode: Globals.tlPowered, InitPinsHi: null, InitPinsLo: null, InitPinsHiz: null);
			
			//OriginalCode: For i = 0 To UBound(InPinsArray);
			//PseudoCode  : ForLoop: VariableName: i; Start: 0; Stop: UBound(InPinsArray); StepSize: 1;
			for (i = 0; i <= GlobalFunctions.UBound(InPinsArray); i = i + 1)
			{
				//OriginalCode: TheExec.Flow.TestLimit VilVoltage(i), ScaleType:=scaleNoScaling, unit:=unitVolt, ForceResults:=tlForceFlow;
				//PseudoCode  : AsIsLineOfCode: LineOfCode: TheExec.Flow.TestLimit(VilVoltage(i), ScaleType:=scaleNoScaling, unit:=unitVolt, ForceResults:=tlForceFlow);
				Globals.TheExec.Flow.TestLimit(VilVoltage[i], ScaleType: Globals.scaleNoScaling, unit: Globals.unitVolt, ForceResults: Globals.tlForceFlow);
				
				//OriginalCode: Next i;
				//PseudoCode  : EndForLoop: VariableName: i;
			}
			
			//OriginalCode: For i = 0 To UBound(InPinsArray);
			//PseudoCode  : ForLoop: VariableName: i; Start: 0; Stop: UBound(InPinsArray); StepSize: 1;
			for (i = 0; i <= GlobalFunctions.UBound(InPinsArray); i = i + 1)
			{
				//OriginalCode: TheExec.Flow.TestLimit VihVoltage(i), ScaleType:=scaleNoScaling, unit:=unitVolt, ForceResults:=tlForceFlow;
				//PseudoCode  : AsIsLineOfCode: LineOfCode: TheExec.Flow.TestLimit(VihVoltage(i), ScaleType:=scaleNoScaling, unit:=unitVolt, ForceResults:=tlForceFlow);
				Globals.TheExec.Flow.TestLimit(VihVoltage[i], ScaleType: Globals.scaleNoScaling, unit: Globals.unitVolt, ForceResults: Globals.tlForceFlow);
				
				//OriginalCode: Next i;
				//PseudoCode  : EndForLoop: VariableName: i;
			}
			
			//OriginalCode: Exit Function;
			//PseudoCode  : FunctionExit;
			return;
			
			//OriginalCode: errHandler:;
			
			//PseudoCode  : FunctionEnd;
		}
		///********************************************************/
		
