			Globals.TheHdw.DCVI.Pins("VDD1").Meter.Filter.Bypass = false;
			
			//OriginalCode: .Connect tlDCVIConnectHighForce + tlDCVIConnectHighSense;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.DCVI.Pins("VDD1").Connect(tlDCVIConnectHighForce + tlDCVIConnectHighSense);
			Globals.TheHdw.DCVI.Pins("VDD1").Connect(Globals.tlDCVIConnectHighForce + Globals.tlDCVIConnectHighSense);
			
			//OriginalCode: TheHdw.Wait 0.001;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Wait(0.001);
			Globals.TheHdw.Wait(0.001);
			
			//OriginalCode: .Gate = True;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.DCVI.Pins("VDD1").Gate = True;
			Globals.TheHdw.DCVI.Pins("VDD1").Gate = true;
			
			//OriginalCode: End With;
			//OriginalCode: With TheHdw.DCVI.Pins("VDD2");
			//OriginalCode: .ComplianceRange(tlDCVIComplianceBoth) = 10;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.DCVI.Pins("VDD2").ComplianceRange(tlDCVIComplianceBoth) = 10;
			Globals.TheHdw.DCVI.Pins("VDD2").ComplianceRange[Globals.tlDCVIComplianceBoth] = 10;
			
			//VDD2 5p5/5p5
			
			//OriginalCode: .SetVoltageAndRange 5.5, 10;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.DCVI.Pins("VDD2").SetVoltageAndRange(5.5, 10);
			Globals.TheHdw.DCVI.Pins("VDD2").SetVoltageAndRange(5.5, 10);
			
			//OriginalCode: .SetCurrentAndRange 0.2, 0.2;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.DCVI.Pins("VDD2").SetCurrentAndRange(0.2, 0.2);
			Globals.TheHdw.DCVI.Pins("VDD2").SetCurrentAndRange(0.2, 0.2);
			
			//OriginalCode: .Meter.Filter.Bypass = False;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.DCVI.Pins("VDD2").Meter.Filter.Bypass = False;
			Globals.TheHdw.DCVI.Pins("VDD2").Meter.Filter.Bypass = false;
			
			//OriginalCode: .Connect tlDCVIConnectHighForce + tlDCVIConnectHighSense;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.DCVI.Pins("VDD2").Connect(tlDCVIConnectHighForce + tlDCVIConnectHighSense);
			Globals.TheHdw.DCVI.Pins("VDD2").Connect(Globals.tlDCVIConnectHighForce + Globals.tlDCVIConnectHighSense);
			
			//OriginalCode: TheHdw.Wait 0.001;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Wait(0.001);
			Globals.TheHdw.Wait(0.001);
			
			//OriginalCode: .Gate = True;
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.DCVI.Pins("VDD2").Gate = True;
			Globals.TheHdw.DCVI.Pins("VDD2").Gate = true;
			
			//OriginalCode: End With;
			//Apply levels and timing
			
			//should I move this inside the active site loop?
			
			//OriginalCode: TheHdw.Digital.ApplyLevelsTiming True, True, True, tlPowered, , "data_ins";
			//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.ApplyLevelsTiming(True, True, True, tlPowered, , "data_ins");
			Globals.TheHdw.Digital.ApplyLevelsTiming(ConnectAllPins: true, loadLevels: true, loadTiming: true, RelayMode: Globals.tlPowered, InitPinsHi: null, InitPinsLo: "data_ins", InitPinsHiz: null);
			
			//Should this be a variable? changed from orig above 2-5-13
			
			//OriginalCode: StepSize = 0.125 * ns;
			//PseudoCode  : VariableAssignment: Name: StepSize; AssignedValue: 0.125 * ns;
			StepSize = 0.125 * Globals.nS;
			
			//OriginalCode: For Each nSite In TheExec.Sites.Active;
			//PseudoCode  : ForEachLoop: ObjectName: nSite; CollectionName: TheExec.Sites.Active;
			foreach (dynamic nSite in Globals.TheExec.Sites.Active)
			{
				GlobalFunctions.BeginSiteLoop(nSite);
				
				//OriginalCode: MaxPropDelay = 0;
				//PseudoCode  : VariableAssignment: Name: MaxPropDelay; AssignedValue: 0;
				MaxPropDelay = 0;
				
				//OriginalCode: NumActiveSites = TheExec.Sites.Active.Count;
				//PseudoCode  : VariableAssignment: Name: NumActiveSites; AssignedValue: TheExec.Sites.Active.Count;
				NumActiveSites = Globals.TheExec.Sites.Active.Count;
				
				//OriginalCode: SiteNum = nSite;
				//PseudoCode  : VariableAssignment: Name: SiteNum; AssignedValue: nSite;
				SiteNum = nSite;
				
				//OriginalCode: For i = 0 To UBound(OutPinsArray);
				//PseudoCode  : ForLoop: VariableName: i; Start: 0; Stop: UBound(OutPinsArray); StepSize: 1;
				for (i = 0; i <= GlobalFunctions.UBound(OutPinsArray); i = i + 1)
				{
					//OriginalCode: If i = 0 Then;
					//PseudoCode  : If: Condition: i = 0;
					if (i == 0)
					{
						//OriginalCode: MaxPropDelay = PropDelayRise(i);
						//PseudoCode  : VariableAssignment: Name: MaxPropDelay; AssignedValue: PropDelayRise(i);
						MaxPropDelay = Globals.PropDelayRise[i].Value[nSite];
						
						//OriginalCode: End If;
					//PseudoCode  : EndIf;
					}
					
					//OriginalCode: If PropDelayRise(i) > MaxPropDelay Then;
					//PseudoCode  : If: Condition: PropDelayRise(i) > MaxPropDelay;
					if (Globals.PropDelayRise[i].Value[nSite] > MaxPropDelay)
					{
						//OriginalCode: MaxPropDelay = PropDelayRise(i);
						//PseudoCode  : VariableAssignment: Name: MaxPropDelay; AssignedValue: PropDelayRise(i);
						MaxPropDelay = Globals.PropDelayRise[i].Value[nSite];
						
						//OriginalCode: End If;
					//PseudoCode  : EndIf;
					}
					
					//OriginalCode: Next i;
					//PseudoCode  : EndForLoop: VariableName: i;
				}
				
				//OriginalCode: Call TheHdw.Digital.Timing.Pins(InPins).ReadEdgeTimingRAM(TsetName);
				//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.Pins(InPins).ReadEdgeTimingRAM(TsetName);
				Globals.TheHdw.Digital.Timing.Pins(InPins).ReadEdgeTimingRAM(TsetName);
				
				//OriginalCode: D0_InputEdge = TheHdw.Digital.Timing.EdgeTime(chEdgeD0);
				//PseudoCode  : VariableAssignment: Name: D0_InputEdge; AssignedValue: TheHdw.Digital.Timing.EdgeTime(chEdgeD0);
				D0_InputEdge = Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeD0];
				
				//OriginalCode: D1_InputEdge = TheHdw.Digital.Timing.EdgeTime(chEdgeD1);
				//PseudoCode  : VariableAssignment: Name: D1_InputEdge; AssignedValue: TheHdw.Digital.Timing.EdgeTime(chEdgeD1);
				D1_InputEdge = Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeD1];
				
				//OriginalCode: D2_InputEdge = TheHdw.Digital.Timing.EdgeTime(chEdgeD2);
				//PseudoCode  : VariableAssignment: Name: D2_InputEdge; AssignedValue: TheHdw.Digital.Timing.EdgeTime(chEdgeD2);
				D2_InputEdge = Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeD2];
				
				//OriginalCode: InputTrailingEdge = TheHdw.Digital.Timing.EdgeTime(chEdgeD2);
				//PseudoCode  : VariableAssignment: Name: InputTrailingEdge; AssignedValue: TheHdw.Digital.Timing.EdgeTime(chEdgeD2);
				InputTrailingEdge = Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeD2];
				
				//OriginalCode: D3_InputEdge = TheHdw.Digital.Timing.EdgeTime(chEdgeD3);
				//PseudoCode  : VariableAssignment: Name: D3_InputEdge; AssignedValue: TheHdw.Digital.Timing.EdgeTime(chEdgeD3);
				D3_InputEdge = Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeD3];
				
				//OriginalCode: R0_InputEdge = TheHdw.Digital.Timing.EdgeTime(chEdgeR0);
				//PseudoCode  : VariableAssignment: Name: R0_InputEdge; AssignedValue: TheHdw.Digital.Timing.EdgeTime(chEdgeR0);
				R0_InputEdge = Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeR0];
				
				//OriginalCode: R1_InputEdge = TheHdw.Digital.Timing.EdgeTime(chEdgeR1);
				//PseudoCode  : VariableAssignment: Name: R1_InputEdge; AssignedValue: TheHdw.Digital.Timing.EdgeTime(chEdgeR1);
				R1_InputEdge = Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeR1];
				
				//make data_out passed through instance
				
				//OriginalCode: TheHdw.Digital.Timing.Pins(OutPins).ReadEdgeTimingRAM (TsetName);
				//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.Pins(OutPins).ReadEdgeTimingRAM(TsetName);
				Globals.TheHdw.Digital.Timing.Pins(OutPins).ReadEdgeTimingRAM(TsetName);
				
				//OriginalCode: R0_OutputEdge = TheHdw.Digital.Timing.EdgeTime(chEdgeR0);
				//PseudoCode  : VariableAssignment: Name: R0_OutputEdge; AssignedValue: TheHdw.Digital.Timing.EdgeTime(chEdgeR0);
				R0_OutputEdge = Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeR0];
				
				//new
				
				//OriginalCode: InitOutputR0Edge = TheHdw.Digital.Timing.EdgeTime(chEdgeR0);
				//PseudoCode  : VariableAssignment: Name: InitOutputR0Edge; AssignedValue: TheHdw.Digital.Timing.EdgeTime(chEdgeR0);
				InitOutputR0Edge = Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeR0];
				
				//OriginalCode: With TheHdw.Digital.Timing;
				//OriginalCode: .EdgeTime(chEdgeR0) = MaxPropDelay + 3 * ns + D1_InputEdge;
				//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.EdgeTime(chEdgeR0) = MaxPropDelay + 3 * ns + D1_InputEdge;
				Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeR0] = MaxPropDelay + 3 * Globals.nS + D1_InputEdge;
				
				//OriginalCode: .Pins(OutPins).WriteEdgeTimingRAM (TsetName);
				//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.Pins(OutPins).WriteEdgeTimingRAM(TsetName);
				Globals.TheHdw.Digital.Timing.Pins(OutPins).WriteEdgeTimingRAM(TsetName);
				
				//OriginalCode: End With;
				//OriginalCode: For i = 0 To UBound(OutPinsArray);
				//PseudoCode  : ForLoop: VariableName: i; Start: 0; Stop: UBound(OutPinsArray); StepSize: 1;
				for (i = 0; i <= GlobalFunctions.UBound(OutPinsArray); i = i + 1)
				{
					//OriginalCode: FailFlag(i)(nSite) = False;
					//PseudoCode  : VariableAssignment: Name: FailFlag(i)(nSite); AssignedValue: False;
					FailFlag[i].Value[nSite] = false;
					
					//OriginalCode: FoundEdge(i) = 0;
					//PseudoCode  : VariableAssignment: Name: FoundEdge(i); AssignedValue: 0;
					FoundEdge[i].Value[nSite] = 0;
					
					//OriginalCode: Next i;
					//PseudoCode  : EndForLoop: VariableName: i;
				}
				
				//OriginalCode: FirstEntry(nSite) = True;
				//PseudoCode  : VariableAssignment: Name: FirstEntry(nSite); AssignedValue: True;
				FirstEntry.Value[nSite] = true;
				
				//OriginalCode: First = True;
				//PseudoCode  : VariableAssignment: Name: First; AssignedValue: True;
				First = true;
				
				//OriginalCode: Done(nSite) = False;
				//PseudoCode  : VariableAssignment: Name: Done(nSite); AssignedValue: False;
				Done.Value[nSite] = false;
				
				//OriginalCode: FailCounter = 0;
				//PseudoCode  : VariableAssignment: Name: FailCounter; AssignedValue: 0;
				FailCounter = 0;
				
				//OriginalCode: While (FailCounter < OutPinsNum);
				//PseudoCode  : WhileLoop: Condition: (FailCounter < OutPinsNum);
				while ((FailCounter < OutPinsNum))
				{
					//Clear Pattern Fail Count
					
					//OriginalCode: For i = 0 To UBound(OutPinsArray);
					//PseudoCode  : ForLoop: VariableName: i; Start: 0; Stop: UBound(OutPinsArray); StepSize: 1;
					for (i = 0; i <= GlobalFunctions.UBound(OutPinsArray); i = i + 1)
					{
						//OriginalCode: TheHdw.Digital.Patgen.ClearFailCount;
						//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Patgen.ClearFailCount();
						Globals.TheHdw.Digital.Patgen.ClearFailCount();
						
						//Run the Pattern
						
						//Call thehdw.Digital.Patterns.Pat(".\\vectors\\func_tPWH_10M").Load
						
						//OriginalCode: Call TheHdw.Digital.Patterns.Pat(".\\vectors\\func_tPWH_10M").Run;
						//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Patterns.Pat(".\\vectors\\func_tPWH_10M").Run();
						Globals.TheHdw.Digital.Patterns.Pat(".\\vectors\\func_tPWH_10M").Run();
						
						//Check Pattern Status
						
						//OriginalCode: FailFlag(i)(nSite) = TheHdw.Digital.PinSiteFailed(OutPinsArray(i), SiteNum);
						//PseudoCode  : VariableAssignment: Name: FailFlag(i)(nSite); AssignedValue: TheHdw.Digital.PinSiteFailed(OutPinsArray(i), SiteNum);
						FailFlag[i].Value[nSite] = Globals.TheHdw.Digital.PinSiteFailed(OutPinsArray[i],SiteNum);
						
						//OriginalCode: If (FailFlag(i)(nSite) = True) And (First = True) Then;
						//PseudoCode  : If: Condition: (FailFlag(i)(nSite) = True) And (First = True);
						if ((FailFlag[i].Value[nSite] == true) && (First == true))
						{
							//OriginalCode: First = False;
							//PseudoCode  : VariableAssignment: Name: First; AssignedValue: False;
							First = false;
							
							//OriginalCode: With TheHdw.Digital.Timing;
							//OriginalCode: .EdgeTime(chEdgeR0) = R0_OutputEdge + 5 * ns;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.EdgeTime(chEdgeR0) = R0_OutputEdge + 5 * ns;
							Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeR0] = R0_OutputEdge + 5 * Globals.nS;
							
							//OriginalCode: .Pins(OutPins).WriteEdgeTimingRAM (TsetName);
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.Pins(OutPins).WriteEdgeTimingRAM(TsetName);
							Globals.TheHdw.Digital.Timing.Pins(OutPins).WriteEdgeTimingRAM(TsetName);
							
							//OriginalCode: End With;
							//OriginalCode: TheHdw.Digital.Patgen.ClearFailCount;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Patgen.ClearFailCount();
							Globals.TheHdw.Digital.Patgen.ClearFailCount();
							
							//Run the Pattern
							
							//Call thehdw.Digital.Patterns.Pat(".\\vectors\\func_tPWH_10M").Load
							
							//OriginalCode: Call TheHdw.Digital.Patterns.Pat(".\\vectors\\func_tPWH_10M").Run;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Patterns.Pat(".\\vectors\\func_tPWH_10M").Run();
							Globals.TheHdw.Digital.Patterns.Pat(".\\vectors\\func_tPWH_10M").Run();
							
							//Check Pattern Status
							
							//OriginalCode: FailFlag(i)(nSite) = TheHdw.Digital.PinSiteFailed(OutPinsArray(i), SiteNum);
							//PseudoCode  : VariableAssignment: Name: FailFlag(i)(nSite); AssignedValue: TheHdw.Digital.PinSiteFailed(OutPinsArray(i), SiteNum);
							FailFlag[i].Value[nSite] = Globals.TheHdw.Digital.PinSiteFailed(OutPinsArray[i],SiteNum);
							
							//OriginalCode: End If;
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: First = False;
						//PseudoCode  : VariableAssignment: Name: First; AssignedValue: False;
						First = false;
						
						//OriginalCode: If (FoundEdge(i) > 0) Then GoTo Continue:;
						//PseudoCode  : If: Condition: (FoundEdge(i) > 0);
						if ((FoundEdge[i].Value[nSite] > 0))
						{
							//PseudoCode  : GoToCommand: Label: Continue;
							goto Continue;
							
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: If (FailFlag(i)(nSite)) Then;
						//PseudoCode  : If: Condition: (FailFlag(i)(nSite));
						if ((FailFlag[i].Value[nSite]))
						{
							//OriginalCode: FailCounter = FailCounter + 1;
							//PseudoCode  : VariableAssignment: Name: FailCounter; AssignedValue: FailCounter + 1;
							FailCounter = FailCounter + 1;
							
							//OriginalCode: FoundEdge(i) = InputTrailingEdge + StepSize;
							//PseudoCode  : VariableAssignment: Name: FoundEdge(i); AssignedValue: InputTrailingEdge + StepSize;
							FoundEdge[i].Value[nSite] = InputTrailingEdge + StepSize;
							
							//OriginalCode: End If;
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: If FailCounter = (UBound(OutPinsArray) + 1) Then;
						//PseudoCode  : If: Condition: FailCounter = (UBound(OutPinsArray) + 1);
						if (FailCounter == (GlobalFunctions.UBound(OutPinsArray) + 1))
						{
							//OriginalCode: Done(nSite) = True;
							//PseudoCode  : VariableAssignment: Name: Done(nSite); AssignedValue: True;
							Done.Value[nSite] = true;
							
							//OriginalCode: NumSitesDone = NumSitesDone + 1;
							//PseudoCode  : VariableAssignment: Name: NumSitesDone; AssignedValue: NumSitesDone + 1;
							NumSitesDone = NumSitesDone + 1;
							
							//OriginalCode: InputTrailingEdge = InputTrailingEdge + StepSize;
							//PseudoCode  : VariableAssignment: Name: InputTrailingEdge; AssignedValue: InputTrailingEdge + StepSize;
							InputTrailingEdge = InputTrailingEdge + StepSize;
							
							//OriginalCode: End If;
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: Continue:;
						//PseudoCode  : GoToLabel: Name: Continue;
Continue:
						
						//OriginalCode: If (i = InPinsNum - 1) Then;
						//PseudoCode  : If: Condition: (i = InPinsNum - 1);
						if ((i == InPinsNum - 1))
						{
							//OriginalCode: InputTrailingEdge = InputTrailingEdge - StepSize;
							//PseudoCode  : VariableAssignment: Name: InputTrailingEdge; AssignedValue: InputTrailingEdge - StepSize;
							InputTrailingEdge = InputTrailingEdge - StepSize;
							
							//OriginalCode: End If;
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: If (InputTrailingEdge >= D1_InputEdge) And (Not Done(nSite)) And (i = InPinsNum - 1) Then;
						//PseudoCode  : If: Condition: (InputTrailingEdge >= D1_InputEdge) And (Not Done(nSite)) And (i = InPinsNum - 1);
						if ((InputTrailingEdge >= D1_InputEdge) && (NotDone.Value[nSite]) && (i == InPinsNum - 1))
						{
							//Set New TrailingEdge (D2_Edge) Location
							
							//OriginalCode: With TheHdw.Digital.Timing;
							//OriginalCode: .EdgeTime(chEdgeD2) = InputTrailingEdge;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.EdgeTime(chEdgeD2) = InputTrailingEdge;
							Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeD2] = InputTrailingEdge;
							
							//OriginalCode: .EdgeTime(chEdgeD1) = D1_InputEdge;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.EdgeTime(chEdgeD1) = D1_InputEdge;
							Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeD1] = D1_InputEdge;
							
							//OriginalCode: .EdgeTime(chEdgeD0) = D0_InputEdge;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.EdgeTime(chEdgeD0) = D0_InputEdge;
							Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeD0] = D0_InputEdge;
							
							//OriginalCode: .EdgeTime(chEdgeD3) = D3_InputEdge;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.EdgeTime(chEdgeD3) = D3_InputEdge;
							Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeD3] = D3_InputEdge;
							
							//OriginalCode: .EdgeTime(chEdgeR0) = R0_InputEdge;
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.EdgeTime(chEdgeR0) = R0_InputEdge;
							Globals.TheHdw.Digital.Timing.EdgeTime[Globals.chEdgeR0] = R0_InputEdge;
							
							//.Pins(InPinsArray(i)).WriteEdgeTimingRAM (TsetName)
							
							//added from original above 2-5-13
							
							//OriginalCode: .Pins(InPins).WriteEdgeTimingRAM (TsetName);
							//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.Timing.Pins(InPins).WriteEdgeTimingRAM(TsetName);
							Globals.TheHdw.Digital.Timing.Pins(InPins).WriteEdgeTimingRAM(TsetName);
							
							//OriginalCode: End With;
							//OriginalCode: End If;
						//PseudoCode  : EndIf;
						}
						
						//OriginalCode: Next i;
						//PseudoCode  : EndForLoop: VariableName: i;
					}
					
					//OriginalCode: Wend;
					//PseudoCode  : EndWhileLoop;
				}
				
				//OriginalCode: TheHdw.Digital.ApplyLevelsTiming True, True, True, tlPowered, , "data_ins";
				//PseudoCode  : AsIsLineOfCode: LineOfCode: TheHdw.Digital.ApplyLevelsTiming(True, True, True, tlPowered, , "data_ins");
				Globals.TheHdw.Digital.ApplyLevelsTiming(ConnectAllPins: true, loadLevels: true, loadTiming: true, RelayMode: Globals.tlPowered, InitPinsHi: null, InitPinsLo: "data_ins", InitPinsHiz: null);
				
				//OriginalCode: Next nSite;
				//PseudoCode  : EndForLoop: VariableName: nSite;
				GlobalFunctions.EndSiteLoop(nSite);
			}
			
			//Datalog Results
			
			//OriginalCode: For i = 0 To UBound(InPinsArray);
			//PseudoCode  : ForLoop: VariableName: i; Start: 0; Stop: UBound(InPinsArray); StepSize: 1;
			for (i = 0; i <= GlobalFunctions.UBound(InPinsArray); i = i + 1)
			{
				//OriginalCode: For Each nSite In TheExec.Sites.Active;
				//PseudoCode  : ForEachLoop: ObjectName: nSite; CollectionName: TheExec.Sites.Active;
				foreach (dynamic nSite in Globals.TheExec.Sites.Active)
				{
					GlobalFunctions.BeginSiteLoop(nSite);
					
					//OriginalCode: If D1_InputEdge >= FoundEdge(i)(nSite) Then;
					//PseudoCode  : If: Condition: D1_InputEdge >= FoundEdge(i)(nSite);
					if (D1_InputEdge >= FoundEdge[i].Value[nSite])
					{
						//OriginalCode: Pulse_width(i)(nSite) = 99;
						//PseudoCode  : VariableAssignment: Name: Pulse_width(i)(nSite); AssignedValue: 99;
						Pulse_width[i].Value[nSite] = 99;
						
						//OriginalCode: Else;
						//PseudoCode  : Else;
					}
					else
					{
						//OriginalCode: Pulse_width(i)(nSite) = FoundEdge(i)(nSite) - D1_InputEdge;
						//PseudoCode  : VariableAssignment: Name: Pulse_width(i)(nSite); AssignedValue: FoundEdge(i)(nSite) - D1_InputEdge;
						Pulse_width[i].Value[nSite] = FoundEdge[i].Value[nSite] - D1_InputEdge;
						
						//OriginalCode: End If;
					//PseudoCode  : EndIf;
					}
					
					//OriginalCode: Next nSite;
					//PseudoCode  : EndForLoop: VariableName: nSite;
					GlobalFunctions.EndSiteLoop(nSite);
				}
				
