			string[] OutPinsArray;
			
			//OriginalCode: Dim FoundEdge() As New SiteDouble;
			//PseudoCode  : VariableDeclaration: Name: FoundEdge(); Type: New SiteDouble;
			SiteDouble[] FoundEdge;
			
			//OriginalCode: Dim D0_InputEdge As Double;
