			double D0_InputEdge = 0;
			
			//OriginalCode: Dim D1_InputEdge As Double;
			//PseudoCode  : VariableDeclaration: Name: D1_InputEdge; Type: Double;
			double D1_InputEdge = 0;
			
			//OriginalCode: Dim D2_InputEdge As Double;
			//PseudoCode  : VariableDeclaration: Name: D2_InputEdge; Type: Double;
