			//PseudoCode  : VariableDeclaration: Name: CO_DIR_CH_CH_RiseFallMaxError(0); Type: New SiteDouble;
			SiteDouble[] CO_DIR_CH_CH_RiseFallMaxError = SiteDouble.New(0);
			
			//OriginalCode: On Error GoTo errHandler;
