			//OriginalCode: If NonBlank(PrebodyUtil0Pins) Then;
			//PseudoCode  : If: Condition: NonBlank(PrebodyUtil0Pins);
			if (NonBlank(PrebodyUtil0Pins))
			{
				//OriginalCode: TheHdw.Utility.Pins(PrebodyUtil0Pins).State = tlUtilBitOff;
